/**
 * BM25 search over the bundled DuckDB documentation (`src/ai/docs/duckdb-docs.json`,
 * generated by `scripts/build-docs.mjs`).
 *
 * Words are matched whole after light stemming, so a model that searches for
 * "truncation" or "splitting" finds sections that say "truncate" or "split".
 * Function names are matched exactly, and snake_case names are also indexed by
 * every run of their parts, so `read_csv_auto` finds the `read_csv` pages. A
 * chunk's heading trail is scored as a separate, heavier field than its text.
 * Tables that list functions with sections of their own rank below those
 * sections: they are long, so the formatter would cut them before the row
 * that matched.
 *
 * Results are formatted for small models: sections with SQL examples are
 * reduced to their examples, each with the sentence or heading introducing
 * it, and examples repeated across sections are shown once.
 *
 * @module ai/docs-search
 */

/** A searchable section of the documentation. */
export interface DocsChunk {
  /** Heading trail, e.g. `SQL › Statements › PIVOT Statement`. */
  path: string;
  /** duckdb.org URL of the section. */
  url: string;
  /** Markdown text. */
  text: string;
}

/** The generated documentation file. */
export interface DocsBundle {
  format: 1;
  /** DuckDB version the documentation describes, e.g. `2.0`. */
  docsVersion: string;
  source?: string;
  lastModified?: string;
  /** Heading trail, page path with optional `#section`, Markdown text. */
  chunks: Array<[string, string, string]>;
}

/** Maximum length of the text a search returns to the model (about 600 tokens). */
export const MAX_DOCS_RESULT_CHARS = 2_500;
/** Maximum length of one section when several are returned, so none crowds out the rest. */
export const MAX_DOCS_SECTION_CHARS = 1_000;
/** Code languages shown as examples. */
const EXAMPLE_LANGUAGES = new Set(['sql', 'plsql']);
/** Longest sentence kept as a section's lead or an example's introduction. */
const MAX_SENTENCE_CHARS = 200;

const K1 = 1.2;
/** Score reduction per heading level below a page's top section; general sections explain basics. */
const DEPTH_PENALTY = 0.15;
const PATH_FIELD = { weight: 3, b: 0.3 };
const TEXT_FIELD = { weight: 1, b: 0.75 };
/** Score factor for a table that lists functions which have sections of their own. */
const OVERVIEW_WEIGHT = 0.5;

/** Query words that carry no meaning here. SQL keywords (to, using, with, do, into, …) are kept. */
const STOPWORDS = new Set([
  'a', 'about', 'an', 'are', 'can', 'could', 'does', 'for', 'how', 'i', 'me', 'my', 'of',
  'please', 'should', 'that', 'the', 'there', 'this', 'what', 'which', 'would',
]);

const WORD = /[a-z0-9_]+/g;

/** Suffixes removed by `stem`, longest first; only one of them is removed. */
const SUFFIXES = ['ings', 'ing', 'ions', 'ion', 'ies', 'ed', 'es', 's', 'e'];

/** Folds simple plurals: `functions` → `function`, `types` → `type`. */
function foldPlural(word: string): string {
  return word.length > 4 && word.endsWith('s') && !/(?:ss|us|is)$/.test(word) ? word.slice(0, -1) : word;
}

/**
 * Light stemming that maps the forms of a word to one term: `truncation`,
 * `truncate`, and `truncated` → `truncat`; `splitting` and `splits` → `split`;
 * `partitioning` and `partition` → `partit`. One suffix is removed, keeping at
 * least four letters (three for a plural `s`), so short words stay intact.
 * Identifiers (with `_` or digits) only lose a plural `s`.
 */
function stem(word: string): string {
  if (/[_0-9]/.test(word)) return foldPlural(word);
  let stemmed = word;
  for (const suffix of SUFFIXES) {
    if (!stemmed.endsWith(suffix) || stemmed.length - suffix.length < (suffix === 's' ? 3 : 4)) continue;
    if (suffix === 's' && /(?:ss|us|is)$/.test(stemmed)) continue;
    stemmed = stemmed.slice(0, -suffix.length) + (suffix === 'ies' ? 'y' : '');
    // splitting → splitt → split, but sniffing → sniff.
    if (/^(?:ings?|ed)$/.test(suffix) && /([b-df-hj-np-tv-z])\1$/.test(stemmed) && !/(?:ll|ss|ff|zz)$/.test(stemmed)) {
      stemmed = stemmed.slice(0, -1);
    }
    break;
  }
  // partitioning → partition → partit, like partition itself.
  if (stemmed !== word && stemmed.endsWith('ion') && stemmed.length >= 7) stemmed = stemmed.slice(0, -3);
  return stemmed;
}

/** Runs of consecutive parts of a snake_case name, excluding the whole name. */
function partRuns(word: string): string[][] {
  const parts = word.split('_').filter(Boolean);
  const runs: string[][] = [];
  for (let start = 0; start < parts.length; start++) {
    for (let end = start + 1; end <= parts.length; end++) {
      if (end - start < parts.length) runs.push(parts.slice(start, end));
    }
  }
  return runs;
}

/** Index terms of a text. */
export function tokenize(text: string): string[] {
  const terms: string[] = [];
  for (const [word] of text.toLowerCase().matchAll(WORD)) {
    terms.push(stem(word));
    if (word.includes('_')) {
      for (const run of partRuns(word)) {
        const term = run.join('_');
        if (term.length >= 2) terms.push(stem(term));
      }
    }
  }
  return terms;
}

/** Weighted terms of a query: whole words count fully, parts of snake_case names less. */
export function queryTerms(query: string): Map<string, number> {
  const words = [...query.toLowerCase().matchAll(WORD)].map(([word]) => word);
  const meaningful = words.filter((word) => !STOPWORDS.has(word));
  const terms = new Map<string, number>();
  const add = (term: string, weight: number) => {
    const stemmed = stem(term);
    terms.set(stemmed, Math.max(terms.get(stemmed) ?? 0, weight));
  };
  for (const word of meaningful.length > 0 ? meaningful : words) {
    add(word, 1);
    if (word.includes('_')) {
      for (const run of partRuns(word)) {
        if (run.length > 1) add(run.join('_'), 0.5);
        else if (run[0].length >= 3) add(run[0], 0.25);
      }
    }
  }
  return terms;
}

function termCounts(text: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const term of tokenize(text)) counts.set(term, (counts.get(term) ?? 0) + 1);
  return counts;
}

/** Converts the generated file into chunks with absolute URLs. */
export function chunksFromBundle(bundle: DocsBundle): DocsChunk[] {
  const base = `https://duckdb.org/docs/${bundle.docsVersion}/`;
  return bundle.chunks.map(([path, page, text]) => ({ path, url: base + page, text }));
}

/** An in-memory BM25 index over documentation chunks. */
export class DocsIndex {
  /** term → flat list of [chunk id, count in path, count in text] */
  private readonly postings = new Map<string, number[]>();
  private readonly pathLengths: Uint32Array;
  private readonly textLengths: Uint32Array;
  private readonly averagePath: number;
  private readonly averageText: number;
  /** Heading levels below the shallowest section of the same page. */
  private readonly depths: Uint8Array;
  /** Whether a chunk contains a SQL example. */
  private readonly hasExamples: Uint8Array;
  /** Whether a chunk is mostly a table of functions that have sections of their own. */
  private readonly overviews: Uint8Array;

  constructor(readonly chunks: readonly DocsChunk[]) {
    this.pathLengths = new Uint32Array(chunks.length);
    this.textLengths = new Uint32Array(chunks.length);
    chunks.forEach((chunk, id) => {
      const pathCounts = termCounts(chunk.path);
      const textCounts = termCounts(chunk.text);
      let pathLength = 0;
      let textLength = 0;
      for (const count of pathCounts.values()) pathLength += count;
      for (const count of textCounts.values()) textLength += count;
      this.pathLengths[id] = pathLength;
      this.textLengths[id] = textLength;
      for (const term of new Set([...pathCounts.keys(), ...textCounts.keys()])) {
        let list = this.postings.get(term);
        if (!list) this.postings.set(term, (list = []));
        list.push(id, pathCounts.get(term) ?? 0, textCounts.get(term) ?? 0);
      }
    });
    const pageOf = (chunk: DocsChunk) => chunk.url.split('#')[0];
    const levels = (chunk: DocsChunk) => chunk.path.replace(/ \(part \d+ of \d+\)$/, '').split(' › ').length;
    const shallowest = new Map<string, number>();
    for (const chunk of chunks) {
      shallowest.set(pageOf(chunk), Math.min(shallowest.get(pageOf(chunk)) ?? Infinity, levels(chunk)));
    }
    this.depths = Uint8Array.from(chunks, (chunk) => Math.min(255, levels(chunk) - (shallowest.get(pageOf(chunk)) ?? 0)));
    this.hasExamples = Uint8Array.from(chunks, (chunk) => (/^\s*```(?:sql|plsql)\s*$/m.test(chunk.text) ? 1 : 0));
    // Sections of single functions end their heading trail with the name, e.g. `date_trunc(part, date)`.
    const ownSections = new Set(chunks.map((chunk) => /`([^`]+)`$/.exec(chunk.path)?.[1]).filter(Boolean));
    this.overviews = Uint8Array.from(chunks, (chunk) => {
      const lines = chunk.text.split('\n').filter((line) => line.trim());
      const rows = lines.filter((line) => ownSections.has(/^\|\s*`([^`]+)`\s*\|/.exec(line)?.[1] ?? ''));
      return rows.length > lines.length / 2 ? 1 : 0;
    });
    const sum = (lengths: Uint32Array) => lengths.reduce((total, length) => total + length, 0);
    this.averagePath = Math.max(1, sum(this.pathLengths) / Math.max(1, chunks.length));
    this.averageText = Math.max(1, sum(this.textLengths) / Math.max(1, chunks.length));
  }

  /**
   * Returns the best chunks for `query` from up to `limit` pages: one chunk per
   * page, plus the best page's runner-up when it scores at least half as high
   * (a page's introduction often lacks the examples of its first subsection).
   * Among such runner-ups, one with SQL examples is preferred.
   */
  search(query: string, limit = 3): DocsChunk[] {
    const total = this.chunks.length;
    const scores = new Map<number, number>();
    for (const [term, queryWeight] of queryTerms(query)) {
      const list = this.postings.get(term);
      if (!list) continue;
      const documentFrequency = list.length / 3;
      const idf = Math.log(1 + (total - documentFrequency + 0.5) / (documentFrequency + 0.5));
      for (let i = 0; i < list.length; i += 3) {
        const id = list[i];
        const tf =
          (PATH_FIELD.weight * list[i + 1]) /
            (1 - PATH_FIELD.b + (PATH_FIELD.b * this.pathLengths[id]) / this.averagePath) +
          (TEXT_FIELD.weight * list[i + 2]) /
            (1 - TEXT_FIELD.b + (TEXT_FIELD.b * this.textLengths[id]) / this.averageText);
        scores.set(id, (scores.get(id) ?? 0) + (queryWeight * idf * tf) / (K1 + tf));
      }
    }

    for (const [id, score] of scores) {
      const overview = this.overviews[id] ? OVERVIEW_WEIGHT : 1;
      scores.set(id, (overview * score) / (1 + DEPTH_PENALTY * this.depths[id]));
    }
    const ranked = [...scores].sort((a, b) => b[1] - a[1] || a[0] - b[0]);
    if (ranked.length === 0 || limit <= 0) return [];
    const pageOf = (id: number) => this.chunks[id].url.split('#')[0];
    const [bestId, bestScore] = ranked[0];
    const candidates = ranked.filter(([id, score]) => id !== bestId && pageOf(id) === pageOf(bestId) && score >= bestScore / 2);
    const runnerUp = candidates.find(([id]) => this.hasExamples[id] === 1) ?? candidates[0];

    const results: DocsChunk[] = [];
    const pages = new Set<string>();
    for (const [id] of ranked) {
      if (pages.has(pageOf(id))) continue;
      pages.add(pageOf(id));
      results.push(this.chunks[id]);
      if (id === bestId && runnerUp) results.push(this.chunks[runnerUp[0]]);
      if (pages.size === limit) break;
    }
    return results;
  }
}

/** A paragraph, a `###` heading, or a code block of a documentation chunk. */
interface Block {
  kind: 'prose' | 'heading' | 'code';
  text: string;
  /** Code language, in lower case. */
  language?: string;
}

/** Splits a chunk's Markdown into paragraphs, `###` headings, and code blocks. */
function blocksOf(text: string): Block[] {
  const blocks: Block[] = [];
  let prose: string[] = [];
  let code: { fence: string; language: string; lines: string[] } | null = null;
  const flushProse = () => {
    const paragraph = prose.join('\n').trim();
    if (paragraph) blocks.push({ kind: 'prose', text: paragraph });
    prose = [];
  };
  for (const line of text.split('\n')) {
    if (code) {
      code.lines.push(line);
      if (line.trim().startsWith(code.fence)) {
        blocks.push({ kind: 'code', text: code.lines.join('\n'), language: code.language });
        code = null;
      }
      continue;
    }
    const fence = /^\s*(```|~~~)\s*([\w+-]*)/.exec(line);
    const heading = /^#{3,6}\s+(.+)$/.exec(line);
    if (fence) {
      flushProse();
      code = { fence: fence[1], language: fence[2].toLowerCase(), lines: [line] };
    } else if (heading) {
      flushProse();
      blocks.push({ kind: 'heading', text: heading[1].trim() });
    } else if (!line.trim()) {
      flushProse();
    } else {
      prose.push(line);
    }
  }
  flushProse();
  if (code) blocks.push({ kind: 'code', text: `${code.lines.join('\n')}\n${code.fence}`, language: code.language });
  return blocks;
}

/** The sentences of a paragraph; inline code such as `CREATE TABLE ... AS SELECT` is never split. */
function sentencesOf(text: string): string[] {
  const flat = text.replace(/\s+/g, ' ').trim();
  const sentences: string[] = [];
  let start = 0;
  let inCode = false;
  for (let i = 0; i < flat.length; i++) {
    if (flat[i] === '`') {
      inCode = !inCode;
    } else if (!inCode && '.!?:'.includes(flat[i]) && flat[i + 1] === ' ' && /[A-Z`*_(]/.test(flat[i + 2] ?? '')) {
      sentences.push(flat.slice(start, i + 1));
      start = i + 2;
    }
  }
  sentences.push(flat.slice(start));
  return sentences.filter(Boolean);
}
const clipSentence = (sentence: string) =>
  sentence.length > MAX_SENTENCE_CHARS ? `${sentence.slice(0, MAX_SENTENCE_CHARS - 1).trimEnd()}…` : sentence;
/** Normalized SQL of a code block, to recognize the same example in several sections. */
const exampleKey = (code: string) =>
  code.replace(/^\s*(```|~~~).*$/gm, '').replace(/\s+/g, ' ').replace(/\s*;\s*$/, '').trim().toLowerCase();

/**
 * A section reduced to its SQL examples, each with its introduction: the
 * paragraph before it when that ends in a colon ("Read a CSV file:"), else the
 * nearest `###` heading, else the paragraph's first sentence. Examples in
 * `seen` are skipped and new ones added. Returns null when no new example fits.
 */
function exampleSection(header: string, blocks: Block[], seen: Set<string>, budget: number, required: number): string | null {
  const firstProse = blocks.findIndex((block) => block.kind === 'prose' && !block.text.startsWith('|'));
  const firstCode = blocks.findIndex((block) => block.kind === 'code' && EXAMPLE_LANGUAGES.has(block.language ?? ''));
  const leadBlock = firstProse !== -1 && firstProse < firstCode ? blocks[firstProse] : null;
  const lead = leadBlock && !(firstProse === firstCode - 1 && leadBlock.text.trimEnd().endsWith(':'))
    ? clipSentence(sentencesOf(leadBlock.text)[0])
    : '';
  let output = lead ? `${header}\n\n${lead}` : header;
  let examples = 0;
  let paragraph: string | null = null;
  let heading: string | null = null;
  for (const block of blocks) {
    if (block.kind === 'heading') {
      heading = block.text;
      paragraph = null;
      continue;
    }
    if (block.kind === 'prose') {
      paragraph = block.text.startsWith('|') ? null : block.text;
      continue;
    }
    const sentences = paragraph ? sentencesOf(paragraph) : [];
    const intro = paragraph?.trimEnd().endsWith(':')
      ? sentences[sentences.length - 1]
      : heading ?? sentences[0] ?? null;
    paragraph = null;
    heading = null;
    if (!EXAMPLE_LANGUAGES.has(block.language ?? '')) continue;
    const key = exampleKey(block.text);
    if (seen.has(key)) continue;
    const entry = intro ? `${clipSentence(intro)}\n${block.text}` : block.text;
    // The first example may use the whole remaining budget, later ones only the section's.
    if (output.length + 2 + entry.length > (examples === 0 ? required : budget)) continue;
    seen.add(key);
    output += `\n\n${entry}`;
    examples++;
  }
  return examples > 0 ? output : null;
}

/** A section without SQL examples (a function's description, a parameter table), shortened to `budget`. */
function textSection(header: string, text: string, budget: number): string | null {
  const full = `${header}\n\n${text}`;
  if (full.length <= budget) return full;
  if (budget < header.length + 200) return null;
  // Room for a closing fence and the ellipsis.
  let excerpt = full.slice(0, budget - 6);
  excerpt = excerpt.slice(0, Math.max(header.length, excerpt.lastIndexOf('\n'))).trimEnd();
  if ((excerpt.match(/^\s*```/gm) ?? []).length % 2 === 1) excerpt += '\n```';
  return `${excerpt}\n…`;
}

/**
 * Formats search results as the tool result the model receives, within
 * `maxChars`: SQL examples first, each example once, and no section longer
 * than MAX_DOCS_SECTION_CHARS when there are several.
 */
export function formatDocsResults(query: string, results: readonly DocsChunk[], maxChars = MAX_DOCS_RESULT_CHARS): string {
  if (results.length === 0) {
    return `No DuckDB documentation matches "${query}". Search for a function name, a statement such as PIVOT, or an error message.`;
  }
  let output = `DuckDB documentation for "${query}":`;
  const seen = new Set<string>();
  for (const chunk of results) {
    const remaining = maxChars - output.length - 2;
    const budget = results.length === 1 ? remaining : Math.min(MAX_DOCS_SECTION_CHARS, remaining);
    const header = `## ${chunk.path}\n${chunk.url}`;
    const blocks = blocksOf(chunk.text);
    const hasExamples = blocks.some((block) => block.kind === 'code' && EXAMPLE_LANGUAGES.has(block.language ?? ''));
    const section = hasExamples
      ? exampleSection(header, blocks, seen, budget, remaining)
      : textSection(header, chunk.text, budget);
    if (section) output += `\n\n${section}`;
  }
  return output;
}
